export type ConfigurationFieldKind = "secret" | "text" | "url";

export interface DefaultEndpointElement {
    base_url:  string;
    dialect:   APIDialect;
    id_suffix: string;
    [property: string]: unknown;
}

/**
 * Secret-free authoring input. Provenance is intentionally absent: external
 * callers cannot claim that a manual value came from a provider or curated source.
 */
export interface PutModelAttributesRequest {
    context_window?:    number | null;
    max_output_tokens?: number | null;
}

/**
 * Resolve an authored profile within a workspace's credential scope.
 */
export interface ResolveProfileRequest {
    workspace_id: string;
    [property: string]: unknown;
}

/**
 * A dry-run resolve request. New callers send a complete `target`; legacy
 * `model_id` remains accepted only when it resolves to exactly one active offering.
 */
export interface ResolveRequest {
    binding:      Binding;
    model_id?:    null | string;
    target?:      null | TargetObject;
    workspace_id: string;
}

/**
 * The "which credential" axis (oversight-next / awaken-management-contract).
 *
 * No credential is needed.
 *
 * Use exactly one source.
 *
 * Use one eligible member of a pool; the resolver selects by policy and may
 * fail over to the next member if the chosen one cannot be materialized.
 */
export interface Binding {
    type:                  Type;
    credential_source_id?: string;
    credential_pool_id?:   string;
    [property: string]: unknown;
}

/**
 * Stable, secret-free identity used to select one catalog offering. `model_id`
 * alone remains accepted for compatibility only when it resolves uniquely.
 */
export interface TargetObject {
    model_id:              string;
    protocol_endpoint_id?: null | string;
    provider_id?:          null | string;
    [property: string]: unknown;
}

/**
 * The ordered candidate list a profile resolves to (E3-2): one secret-free view per
 * model in the profile's axis, in failover order.
 */
export interface ResolvedCandidatesView {
    candidates: CandidateElement[];
    [property: string]: unknown;
}

/**
 * The **secret-free** result of a resolve (ADR-0043): the execution triple + the
 * adapter/endpoint it binds to, and whether a credential resolved — never the
 * secret itself. This is what an operator's "test binding" call sees.
 */
export interface CandidateElement {
    adapter_kind: string;
    base_url?:    null | string;
    /**
     * Whether a credential was materialized (never the value).
     */
    credential_present:   boolean;
    model_id:             string;
    protocol_endpoint_id: string;
    provider_id:          string;
    [property: string]: unknown;
}

/**
 * The **secret-free** result of a resolve (ADR-0043): the execution triple + the
 * adapter/endpoint it binds to, and whether a credential resolved — never the
 * secret itself. This is what an operator's "test binding" call sees.
 */
export interface ResolvedInferenceView {
    adapter_kind: string;
    base_url?:    null | string;
    /**
     * Whether a credential was materialized (never the value).
     */
    credential_present:   boolean;
    model_id:             string;
    protocol_endpoint_id: string;
    provider_id:          string;
    [property: string]: unknown;
}

export interface SaveProviderConnectionRequest {
    base_url?:    null | string;
    dialect:      APIDialect;
    display_name: string;
    endpoint_id:  string;
    provider_id:  string;
    /**
     * Write-only API key. It is tested before entering the vault and never
     * appears in the response or any catalog row.
     */
    secret:        string;
    timeout_secs?: number;
    workspace_id:  string;
    [property: string]: unknown;
}

/**
 * Live-validate a credential against a model's resolved provider endpoint.
 */
export interface ValidateCredentialRequest {
    model_id:     string;
    workspace_id: string;
    [property: string]: unknown;
}
